#include <iostream>
#include <vector>

// Function to find the n-th number in the sequence
int findNthNumber(int n, std::vector<int>& sequence) {
    // Base cases
    if (n == 0) return 0;
    else if (n == 1) return -1;
    else if (n == 2) return -1;

    // Initialize the first three numbers of the sequence
    if (sequence.size() < 3)
        sequence = std::vector<int>{0, -1, -1};

    // If n is greater than the sequence size, we need to calculate more numbers in the sequence
    while (sequence.size() < n + 1) {
        int nextNumber = sequence.back() + sequence[sequence.size() - 2] + sequence[sequence.size() - 3];
        sequence.push_back(nextNumber);
    }

    // Return the n-th number in the sequence
    return sequence[n];
}

int main() {
    int n;

    // Input from user for the position in the sequence
    std::cout << "Enter the position (n) in the sequence: ";
    std::cin >> n;

    // Initialize the sequence
    std::vector<int> sequence;

    // Compute and print the n-th number in the sequence
    std::cout << "The " << n << "-th number in the sequence is: " << findNthNumber(n, sequence) << std::endl;

    return 0;
}
```

