using namespace std;

/**
 * Finds the majority element in an integer array using the Boyer-Moore Voting Algorithm.
 * The majority element is the element that appears more than n/2 times in the array,
 * where n is the size of the array.
 *
 * @param arr The input integer array.
 * @param size The size of the array.
 * @return The majority element if it exists, otherwise -1.
 */
int findMajorityElement(int arr[], int size) {
    int count = 0;
    int candidate = -1;

    // Phase 1: Search for the potential candidate
    for (int i = 0; i < size; ++i) {
        if (count == 0) {
            candidate = arr[i];
        }
        count += (arr[i] == candidate) ? 1 : -1;
    }

    // Phase 2: Verify if the candidate is indeed the majority
    count = 0;
    for (int i = 0; i < size; ++i) {
        if (arr[i] == candidate) {
            count++;
        }
    }

    // Return the majority element if the condition is met, otherwise return -1
    return (2 * count > size) ? candidate : -1;
}

// Function to check the correctness of the findMajorityElement function
void checkMajorityElement() {
    assert(findMajorityElement({3, 3, 4, 2, 4, 4, 2, 4, 4}, 9) == 4);
    assert(findMajorityElement({3, 3, 4, 2, 4, 4, 2, 4}, 8) == -1); // No majority element
    assert(findMajorityElement({5, 5, 5, 7, 5}, 5) == 5);
    assert(findMajorityElement({1, 1, 2, 2, 1}, 5) == 1);
    cout << "All test cases passed successfully." << endl;
}

int main() {
    checkMajorityElement();
    return 0;
}
