Finding the two most occurring elements in an array can be efficiently done using a counting map and sorting the elements in descending order of their frequency. Here is a solution in C++:

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <assert.h>

using namespace std;

// Function to find the top two occurring elements in an array
vector<int> findTopTwo(int arr[], int size) {
    unordered_map<int, int> frequencyMap;
    // Count the frequency of each number in the array
    for (int num : arr) {
        frequencyMap[num]++;
    }
    // Sort the array by frequency in descending order
    vector<pair<int, int>> sortedFreq(frequencyMap.begin(), frequencyMap.end());
    sort(sortedFreq.begin(), sortedFreq.end(), greater<pair<int, int>>());
    // Take top two elements and add them into the result vector
    vector<int> result;
    for (int i = 0; i < min(2, (int)sortedFreq.size()); i++) {
        result.push_back(sortedFreq[i].first);
    }
    return result;
}

void checkTopTwo() {
    assert(findTopTwo({1, 3, 3, 3, 5, 5, 5, 6, 6}, 9) == vector<int>({5, 3}));
    assert(findTopTwo({1, 2, 2, 3, 3, 3}, 6) == vector<int>({3, 2}));
    assert(findTopTwo({9, 8, 7, 7, 6, 6, 6}, 7) == vector<int>({6, 7}));
    assert(findTopTwo({-1, -2, -3, -4, -5, -6}, 6) == vector<int>({-1, -2}));
    cout << "All test cases passed successfully." << endl;
}

int main() {
    checkTopTwo();
    return 0;
}
```

