from typing import List

def find_kth_smallest(list1: List[int], list2: List[int], k: int) -> int:
    """
    Finds the kth smallest element in the union of two sorted lists.

    Args:
    list1: List[int] - First sorted list.
    list2: List[int] - Second sorted list.
    k: int - The kth position (1-indexed) to find in the merged list.

    Returns:
    int - The kth smallest element in the merged list.
    """
    def find_element(index1, index2, kth_from_start):
        if index1 >= len(list1):
            return list2[index2 + kth_from_start - 1]
        if index2 >= len(list2):
            return list1[index1 + kth_from_start - 1]
        if kth_from_start == 1:
            return min(list1[index1], list2[index2])

        mid_from_start_list1 = min(kth_from_start // 2, len(list1) - index1)
        mid_from_start_list2 = min(kth_from_start // 2, len(list2) - index2)

        if list1[index1 + mid_from_start_list1 - 1] <= list2[index2 + mid_from_start_list2 - 1]:
            return find_element(index1 + mid_from_start_list1, index2, kth_from_start - mid_from_start_list1)
        else:
            return find_element(index1, index2 + mid_from_start_list2, kth_from_start - mid_from_start_list2)

    return find_element(1, 1, k)

# Check function to verify the solution
def check_solution():
    assert find_kth_smallest([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
    assert find_kth_smallest([1, 1, 2, 3], [4, 5, 6, 7], 4) == 4
    assert find_kth_smallest([1, 2], [3, 4], 2) == 2
    print("All tests passed!")

check_solution()
```

This solution employs a binary search approach to efficiently find the kth smallest element in the union of two sorted lists. It recursively divides the problem into smaller subproblems until it finds the correct position for the kth element.

